/**
 * The one PostgreSQL image of the project: compose.dev.yaml, Testcontainers and (task 23)
 * production use exactly this tag — a test compares compose.dev.yaml with it.
 *
 * Debian (trixie), not alpine (owner, 2026-11-22): alpine's musl libc has no real locales,
 * so text sorts by bytes; German umlauts and Cyrillic must sort as people expect.
 * 18: uuidv7() is built in (ADR-0008, ids generated by the database).
 */
export const POSTGRES_IMAGE = 'postgres:18.7-trixie';
